package vn.smartfarm.iot.control;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import org.springframework.web.server.ResponseStatusException;
import vn.smartfarm.iot.irrigation.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=true","smartfarm.control.pump-fencing-enabled=true","smartfarm.control.circuit-route-required=true","smartfarm.irrigation.circuit-demo-enabled=true","smartfarm.irrigation.session-enabled=true"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class IrrigationSessionTest {
 @Autowired PumpService pump;@Autowired PumpCommandFencing fencing;@Autowired PumpCircuitProof proof;@Autowired CircuitValveControl valves;@Autowired IrrigationCircuits circuits;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired MockMvc mvc;
 @MockitoBean CommandTransport transport;@MockitoBean CircuitValveTransport valveTransport;
 UUID boot=UUID.fromString("88000000-0000-4000-8000-000000000001"),vboot=UUID.fromString("88000000-0000-4000-8000-000000000002");PumpCircuitRoute route;
 @BeforeEach void setup()throws Exception{cleanup();jdbc.execute("TRUNCATE pump_command,pump_status,pump_state_history,watering_run,watering_rule");jdbc.update("INSERT INTO watering_rule(singleton) VALUES(1)");reset(transport,valveTransport);when(transport.controlConnected()).thenReturn(true);when(valveTransport.circuitValveConnected(anyString())).thenReturn(true);
  for(int i=1;i<=2;i++){jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES(?,?,'AREA001','SOIL',2)","PRSOIL"+i,"Soil");for(int j=1;j<=3;j++)jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES(?,?,'SOIL_MOISTURE','%')","PRSOIL"+i,"SOIL"+j);jdbc.update("INSERT INTO irrigation_zone(zone_id,name,area_id,soil_node_id,expected_source,dry_threshold,wet_threshold) VALUES(?,?,'AREA001',?,'SIMULATOR',30,35)","PRZONE"+i,"Zone","PRSOIL"+i);}
  jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('PRWATER','Water','AREA001','WATER',2)");jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('PRWATER','LOW','WATER_PRESENT','boolean'),('PRWATER','FLOW','FLOW_RATE','L/min')");
  for(int i=1;i<=2;i++)jdbc.update("INSERT INTO irrigation_circuit(circuit_id,name,zone_id,zone_revision,controller_id,valve_id,pump_id,water_node_id,low_channel_id,flow_channel_id,expected_source) VALUES(?,?,?,1,?,?,'PUMP01','PRWATER','LOW','FLOW','SIMULATOR')","PR"+i,"Circuit","PRZONE"+i,"IRRIGATION"+(77+i),"VALVE"+(77+i));
  route=PumpCircuitRoute.from(circuits.find("PR1"));reportPump(1,0,"OFF",route);reportValve("PR1",1,0,"CLOSED");reportValve("PR2",1,0,"CLOSED");
 }
 @AfterEach void after(){cleanup();jdbc.execute("TRUNCATE pump_command,pump_status,pump_state_history,watering_run,watering_rule");jdbc.update("INSERT INTO watering_rule(singleton) VALUES(1)");}
 void cleanup(){jdbc.update("DELETE FROM irrigation_session_action WHERE session_id IN(SELECT session_id FROM irrigation_session WHERE circuit_id IN ('PR1','PR2'))");jdbc.update("DELETE FROM irrigation_session WHERE circuit_id IN ('PR1','PR2')");for(String t:List.of("circuit_demo_command","circuit_demo_status","circuit_demo_boot","circuit_demo_gate"))jdbc.update("DELETE FROM "+t+" WHERE valve_id IN ('VALVE78','VALVE79')");jdbc.update("DELETE FROM irrigation_circuit WHERE circuit_id IN ('PR1','PR2')");jdbc.update("DELETE FROM irrigation_zone WHERE zone_id IN ('PRZONE1','PRZONE2')");jdbc.update("DELETE FROM iot_node WHERE node_id IN ('PRSOIL1','PRSOIL2','PRWATER')");}
 ObjectNode pumpPacket(long sequence,long ordinal,String state,PumpCircuitRoute r){var p=mapper.createObjectNode().put("schemaVersion",1).put("deviceId","PUMP01").put("bootId",boot.toString()).put("sequence",sequence).put("timestamp",Instant.now().toString()).put("connection","ONLINE").put("reportedState",state).put("safetyLockout",false).put("stateReason",state.equals("ON")?"COMMAND_ON":"COMMAND_OFF");p.putObject("commandFence").put("version",1).put("lastOrdinal",ordinal).put("restartRequired",false);var f=p.putObject("valveInterlock").put("version",1).put("enabled",true).put("dataSource","SIMULATOR").put("state","OPEN").putNull("fault");if(r!=null)f.set("route",mapper.valueToTree(r));return p;}
 void reportPump(long sequence,long ordinal,String state,PumpCircuitRoute r)throws Exception{pump.receive("smartfarm/FARM001/PUMP01/status",mapper.writeValueAsBytes(pumpPacket(sequence,ordinal,state,r)));}
 ObjectNode valvePacket(String id,long seq,long ordinal,String state){var c=circuits.find(id);var p=mapper.createObjectNode().put("schemaVersion",1).put("controlProfile",CircuitValveControl.PROFILE).put("controllerId",c.controllerId()).put("actuatorId",c.valveId()).put("circuitId",id).put("circuitRevision",c.revision()).put("zoneId",c.zoneId()).put("zoneRevision",c.zoneRevision()).put("bootId",vboot.toString()).put("sequence",seq).put("timestamp",Instant.now().toString()).put("dataSource","SIMULATOR").put("feedbackState",state).put("gpioState",state).put("reason",state.equals("OPEN")?"COMMAND_OPEN":"COMMAND_CLOSE").put("demoEnabled",true).put("lastOrdinal",ordinal);p.putObject("positionFeedback").put("version",1).put("enabled",true).put("state",state).putNull("fault");return p;}
 void valveReceive(String id,ObjectNode p)throws Exception{valves.receive(CircuitValveControl.topic(circuits.find(id).valveId(),p.has("commandId")?"ack":"status"),mapper.writeValueAsBytes(p),false);}
 void reportValve(String id,long seq,long ordinal,String state)throws Exception{valveReceive(id,valvePacket(id,seq,ordinal,state));}
 CircuitValveControl.Request vrequest(String id,String action){var c=circuits.find(id);return new CircuitValveControl.Request(UUID.randomUUID(),action,action.equals("OPEN")?30:null,vboot,c.revision(),c.zoneRevision(),Instant.now());}
 CircuitValveControl.Command openValve()throws Exception{var c=valves.create("PR1",vrequest("PR1","OPEN"));var p=valvePacket("PR1",2,c.ordinal(),"OPEN").put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action","OPEN").put("result","EXECUTED").putNull("errorCode");valveReceive("PR1",p);reportValve("PR1",3,c.ordinal(),"OPEN");return c;}
 PumpCommandFencing.HttpIntent request(String action,Integer seconds,PumpCircuitRoute r){var v=fencing.view().intent();return new PumpCommandFencing.HttpIntent(UUID.randomUUID(),action,seconds,action.equals("OFF")?null:boot,v.revision(),v.asOf(),r);}
 PumpCommandFencing.Receipt start() {return fencing.createHttp(request("ON",5,route),()->{});}
 long ordinal(UUID id){return jdbc.queryForObject("SELECT fence_ordinal FROM pump_command WHERE command_id=?",Long.class,id);}

 @Autowired IrrigationSession service;@Autowired org.springframework.transaction.PlatformTransactionManager manager;
 IrrigationSession.Run begin(){var v=service.snapshot("PR1");return service.start("PR1",new IrrigationSession.Start(UUID.randomUUID(),1,1,boot,vboot,5,v.asOf()));}
 IrrigationSession.Action stepRequest(IrrigationSession.Run r,String action){return new IrrigationSession.Action(UUID.randomUUID(),action,r.revision(),service.snapshot("PR1").asOf());}
 IrrigationSession.Receipt step(IrrigationSession.Run r,String action){return service.act("PR1",r.sessionId(),stepRequest(r,action));}
 void opened(IrrigationSession.Run r)throws Exception{var c=valves.lookup("PR1",r.openId());valveReceive("PR1",valvePacket("PR1",2,c.ordinal(),"OPEN").put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action","OPEN").put("result","EXECUTED").putNull("errorCode"));reportValve("PR1",3,c.ordinal(),"OPEN");reportPump(2,0,"OFF",route);}
 void acknowledgedOff(IrrigationSession.Run r)throws Exception{jdbc.update("UPDATE pump_command SET state='EXECUTED',reported_state='OFF' WHERE command_id=?",r.offId());if(r.onId()!=null)jdbc.update("UPDATE pump_command SET state='EXECUTED',reported_state='ON',ack_boot_id=?,ack_sequence=3 WHERE command_id=?",boot,r.onId());reportPump(5,ordinal(r.offId()),"OFF",route);}
 void closed(IrrigationSession.Run r)throws Exception{var c=valves.lookup("PR1",r.closeId());valveReceive("PR1",valvePacket("PR1",6,c.ordinal(),"CLOSED").put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action","CLOSE").put("result","EXECUTED").putNull("errorCode"));reportValve("PR1",7,c.ordinal(),"CLOSED");}
 @Test void creationIsDurableButDoesNotPublish()throws Exception{var r=begin();assertEquals("PREPARED",r.phase());assertTrue(service.snapshot("PR1").canOpen());verify(transport,never()).publishCommand(any());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void duplicateStartReturnsSameRunAndChangedBodyConflicts(){var v=service.snapshot("PR1");var q=new IrrigationSession.Start(UUID.randomUUID(),1,1,boot,vboot,5,v.asOf());var r=service.start("PR1",q);assertEquals(r,service.start("PR1",q));assertThrows(ResponseStatusException.class,()->service.start("PR1",new IrrigationSession.Start(q.sessionId(),1,1,boot,vboot,6,v.asOf())));}
 @Test void onlyOneSessionClaimsPumpAndSecondCircuitCannotOperateIt(){var r=begin();assertFalse(service.snapshot("PR2").canStart());assertFalse(service.snapshot("PR2").canOff());assertThrows(ResponseStatusException.class,this::begin);assertThrows(ResponseStatusException.class,()->service.act("PR2",r.sessionId(),stepRequest(r,"OFF")));}
 @Test void openAndOnCannotBeSkippedOrReplayed()throws Exception{var r=begin();assertThrows(ResponseStatusException.class,()->step(r,"ON"));var a=stepRequest(r,"OPEN");var opened=service.act("PR1",r.sessionId(),a);assertEquals("WAIT_OPEN",opened.session().phase());service.act("PR1",r.sessionId(),a);verify(valveTransport,times(1)).publishCircuitValve(anyString(),any());assertThrows(ResponseStatusException.class,()->step(opened.session(),"OPEN"));assertFalse(service.snapshot("PR1").canOn());}
 @Test void fullOperatorFlowNeedsFreshEvidenceForEveryStep()throws Exception{var r=step(begin(),"OPEN").session();opened(r);assertTrue(service.snapshot("PR1").canOn());r=step(r,"ON").session();assertEquals("WAIT_ON",r.phase());assertFalse(service.snapshot("PR1").canClose());r=step(r,"OFF").session();assertFalse(service.snapshot("PR1").canClose());acknowledgedOff(r);assertTrue(service.snapshot("PR1").canClose());r=step(r,"CLOSE").session();assertEquals("WAIT_CLOSED",r.phase());assertFalse(service.snapshot("PR1").canFinish());closed(r);assertTrue(service.snapshot("PR1").canFinish());r=step(r,"FINISH").session();assertEquals("CLOSED_CONFIRMED",r.phase());assertNull(service.snapshot("PR1").active());}
 @Test void outsideOnResetAndValveCommandsCannotStealSession()throws Exception{begin();assertThrows(ResponseStatusException.class,()->pump.create(new PumpService.Request("ON",5)));assertThrows(ResponseStatusException.class,()->fencing.createHttp(request("RESET_LOCKOUT",null,route),()->{}));assertThrows(ResponseStatusException.class,()->valves.create("PR2",vrequest("PR2","OPEN")));assertThrows(ResponseStatusException.class,()->valves.create("PR1",vrequest("PR1","CLOSE")));}
 @Test void editsAreBlockedEvenBeforeOpening(){begin();assertThrows(ResponseStatusException.class,()->circuits.update("PR1",mapper.valueToTree(circuits.find("PR1"))));var c=(ObjectNode)mapper.valueToTree(circuits.find("PR2"));c.remove("revision");c.put("circuitId","PRNEW");assertThrows(ResponseStatusException.class,()->circuits.create(c));}
 @Test void externalOffInterruptsFlowAndPreventsFutureOn()throws Exception{var r=step(begin(),"OPEN").session();opened(r);fencing.createHttp(request("OFF",null,null),()->{});var now=service.find("PR1",r.sessionId());assertEquals("RECOVERY_REQUIRED",now.phase());assertTrue(now.stopRequested());assertFalse(service.snapshot("PR1").canOn());assertThrows(ResponseStatusException.class,()->step(now,"ON"));}
 @Test void restartPausesEveryPhaseWithoutSendingOrReplaying()throws Exception{var r=step(begin(),"OPEN").session();opened(r);clearInvocations(transport,valveTransport);service.interruptOnStartup();assertEquals("RECOVERY_REQUIRED",service.find("PR1",r.sessionId()).phase());assertFalse(service.snapshot("PR1").canOn());assertFalse(service.snapshot("PR1").canOpen());verify(transport,never()).publishCommand(any());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void uncertainOpenKeepsIdentityAndNeverRetries()throws Exception{doThrow(new IllegalStateException()).when(valveTransport).publishCircuitValve(anyString(),any());var r=begin();var q=stepRequest(r,"OPEN");var a=service.act("PR1",r.sessionId(),q);assertEquals("PUBLISH_UNCERTAIN",a.operation().result().path("state").asText());service.act("PR1",r.sessionId(),q);verify(valveTransport,times(1)).publishCircuitValve(anyString(),any());assertFalse(service.snapshot("PR1").canOn());}
 @Test void noMqttOnStartIsNotReadyAndDefaultFlagCanDisableCreation()throws Exception{when(transport.controlConnected()).thenReturn(false);assertFalse(service.snapshot("PR1").canStart());assertThrows(ResponseStatusException.class,this::begin);var disabled=new IrrigationSession(jdbc,mapper,circuits,valves,pump,fencing,proof,manager,false,false);disabled.interruptOnStartup();assertFalse(disabled.snapshot("PR1").canStart());}
 @Test void staleReviewsAndChangedRevisionCannotAdvance(){var r=begin();assertThrows(ResponseStatusException.class,()->service.act("PR1",r.sessionId(),new IrrigationSession.Action(UUID.randomUUID(),"OPEN",r.revision(),Instant.now().minusSeconds(30))));assertThrows(ResponseStatusException.class,()->service.act("PR1",r.sessionId(),new IrrigationSession.Action(UUID.randomUUID(),"OPEN",r.revision()+1,Instant.now())));}
 @Test void closeMayTargetNewValveBootAfterExplicitStop()throws Exception{var r=step(begin(),"OFF").session();acknowledgedOff(r);vboot=UUID.randomUUID();reportValve("PR1",2,0,"CLOSED");var c=step(r,"CLOSE");assertEquals(vboot,valves.lookup("PR1",c.session().closeId()).bootId());}
 @Test void concurrentOpenClicksPublishOnlyOnce()throws Exception{var r=begin();var a=stepRequest(r,"OPEN");var b=stepRequest(r,"OPEN");var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{var jobs=pool.invokeAll(List.<java.util.concurrent.Callable<Boolean>>of(()->{try{service.act("PR1",r.sessionId(),a);return true;}catch(ResponseStatusException e){return false;}},()->{try{service.act("PR1",r.sessionId(),b);return true;}catch(ResponseStatusException e){return false;}}));assertEquals(1,jobs.stream().filter(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).count());}finally{pool.shutdownNow();}verify(valveTransport,times(1)).publishCircuitValve(anyString(),any());}
 @Test void offDuringOpenPublishCannotBeOverwrittenByLateStepReturn()throws Exception{doAnswer(a->{fencing.createHttp(request("OFF",null,null),()->{});return null;}).when(valveTransport).publishCircuitValve(anyString(),any());var r=step(begin(),"OPEN").session();assertEquals("RECOVERY_REQUIRED",r.phase());assertTrue(r.stopRequested());}
 @Test void getAndLookupNeverReissueRequestsOrChangeRevision()throws Exception{var r=step(begin(),"OPEN").session();clearInvocations(transport,valveTransport);var before=jdbc.queryForObject("SELECT row_to_json(s)::text FROM irrigation_session s WHERE session_id=?",String.class,r.sessionId());service.snapshot("PR1");service.operation("PR1",r.openId());mvc.perform(get("/api/v1/irrigation-circuits/PR1/session")).andExpect(status().isOk()).andExpect(jsonPath("$.mode").value("OPERATOR_STEPS"));assertEquals(before,jdbc.queryForObject("SELECT row_to_json(s)::text FROM irrigation_session s WHERE session_id=?",String.class,r.sessionId()));verify(transport,never()).publishCommand(any());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
 @Test void operationAndDispatchPhaseCommitBeforeTransport()throws Exception{var r=begin();doAnswer(a->{var payload=mapper.readTree((byte[])a.getArgument(1));var op=service.operation("PR1",UUID.fromString(payload.path("commandId").asText()));assertEquals("RESERVED",op.state());assertEquals("DISPATCHING_OPEN",service.find("PR1",r.sessionId()).phase());return null;}).when(valveTransport).publishCircuitValve(anyString(),any());step(r,"OPEN");}
 @Test void offDuringOnPublishLeavesRecoveryAndNeverRestoresWaitOn()throws Exception{var r=step(begin(),"OPEN").session();opened(r);doAnswer(a->{var packet=mapper.readTree((byte[])a.getArgument(0));if(packet.path("action").asText().equals("ON"))fencing.createHttp(request("OFF",null,null),()->{});return null;}).when(transport).publishCommand(any());var result=step(r,"ON");assertEquals("RECOVERY_REQUIRED",result.session().phase());assertTrue(result.session().stopRequested());assertFalse(service.snapshot("PR1").canOn());}
 @Test void disablingNewFeatureStillPermitsSafetyOffForExistingSession(){var r=begin();var disabled=new IrrigationSession(jdbc,mapper,circuits,valves,pump,fencing,proof,manager,false,false);assertFalse(disabled.snapshot("PR1").canOpen());var q=stepRequest(r,"OFF");assertEquals("WAIT_OFF",disabled.act("PR1",r.sessionId(),q).session().phase());}
 @Test void closeAckAloneCannotFinishWithoutMatchingNewClosedStatus()throws Exception{var r=step(begin(),"OFF").session();acknowledgedOff(r);r=step(r,"CLOSE").session();var c=valves.lookup("PR1",r.closeId());valveReceive("PR1",valvePacket("PR1",6,c.ordinal(),"CLOSED").put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action","CLOSE").put("result","EXECUTED").putNull("errorCode"));assertFalse(service.snapshot("PR1").canFinish());assertThrows(ResponseStatusException.class,()->step(service.find("PR1",circuitSession(c.commandId())),"FINISH"));}
 UUID circuitSession(UUID action){return jdbc.queryForObject("SELECT session_id FROM irrigation_session_action WHERE request_id=?",UUID.class,action);}

}
